      <div id="html-ed-fields" style="display:flex; flex-direction:column; gap:10px;"></div>
      <div style="display:flex; gap:10px; justify-content:flex-end; margin-top:14px;">
        <button class="btn" onclick="saveDirectHtmlSections(false)">💾 Save Live HTML Only (Instant)</button>
        <button class="btn btn-primary" onclick="saveDirectHtmlSections(true)">⚡ Save & Re-Render Drive PDF (WF2/WF3)</button>
      </div>
    </div>
  </div>

  <div id="toast-box"></div>

  <script>
    const API_URL = window.location.origin + '/webhook/job-dashboard-api';
    const AUTH_URL = window.location.origin + '/webhook/job-dashboard';

    let STATE = {
      authenticated: false, userEmail: '', jobs: [], counts: {}, byPortal: {}, byCategory: {},
      learnedRules: [], liLogs: [], fhContacts: [], liStats: {}, vaultRows: [], socialSsoRows: [],
      limitRows: [], masterResume: {}, selectedSno: '1', studioBucketFilter: 'ALL',
      cmdTab: 'analytics', previewDoc: 'resume', previewMode: 'sheet', tableSortCol: 'sNoNum', tableSortAsc: false, fhFilter: 'ALL'
    };

    function showToast(msg, color = '#38bdf8') {
      const box = document.getElementById('toast-box');
      const el = document.createElement('div');
      el.className = 'toast';
      el.style.borderLeftColor = color;
      el.textContent = msg;
      box.appendChild(el);
      setTimeout(() => { el.remove(); }, 4500);
    }

    function escHtml(str) {
      return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function setCookieVal(name, val, days = 30) {
      try {
        const maxAge = days * 86400;
        document.cookie = `${name}=${encodeURIComponent(val)}; path=/; max-age=${maxAge}; SameSite=Lax`;
      } catch (e) {}
    }

    function getCookieVal(name) {
      try {
        const m = document.cookie.match(new RegExp('(?:^|; )' + name + '=([^;]*)'));
        return m ? decodeURIComponent(m[1]) : '';
      } catch (e) { return ''; }
    }

    function saveUiState() {
      const ui = {
        appMode: STATE.appMode || 'studio',
        cmdTab: STATE.cmdTab || 'analytics',
        selectedSno: STATE.selectedSno || '1',
        studioBucketFilter: STATE.studioBucketFilter || 'ALL',
        previewDoc: STATE.previewDoc || 'resume',
        previewMode: STATE.previewMode || 'sheet'
      };
      const raw = JSON.stringify(ui);
      try { localStorage.setItem('careerpulse_ui_state_v3', raw); } catch (e) {}
      try { sessionStorage.setItem('careerpulse_ui_state_v3', raw); } catch (e) {}
      setCookieVal('cp_ui_state_v3', raw, 30);
      try {
        const hash = `#mode=${encodeURIComponent(ui.appMode)}&tab=${encodeURIComponent(ui.cmdTab)}&job=${encodeURIComponent(ui.selectedSno)}&doc=${encodeURIComponent(ui.previewDoc)}`;
        window.history.replaceState(null, '', hash);
      } catch (e) {}
    }

    function restoreUiState() {
      try {
        const raw = localStorage.getItem('careerpulse_ui_state_v3') || sessionStorage.getItem('careerpulse_ui_state_v3') || getCookieVal('cp_ui_state_v3');
        if (raw) {
          const ui = JSON.parse(raw);
          if (ui.appMode) STATE.appMode = ui.appMode;
          if (ui.cmdTab) STATE.cmdTab = ui.cmdTab;
          if (ui.selectedSno) STATE.selectedSno = String(ui.selectedSno);
          if (ui.studioBucketFilter) STATE.studioBucketFilter = ui.studioBucketFilter;
          if (ui.previewDoc) STATE.previewDoc = ui.previewDoc;
          if (ui.previewMode) STATE.previewMode = ui.previewMode;
        }
        if (window.location.hash && window.location.hash.length > 1) {
          const params = new URLSearchParams(window.location.hash.slice(1));
          if (params.get('mode')) STATE.appMode = params.get('mode');
          if (params.get('tab')) STATE.cmdTab = params.get('tab');
          if (params.get('job')) STATE.selectedSno = params.get('job');
          if (params.get('doc')) STATE.previewDoc = params.get('doc');
        }
      } catch (e) {}
    }

    function checkSavedSession() {
      try {
        const raw = localStorage.getItem('careerpulse_oauth_session')
          || sessionStorage.getItem('careerpulse_oauth_session')
          || getCookieVal('cp_oauth_session');
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && parsed.email && parsed.token) {
            STATE.authenticated = true;
            STATE.userEmail = parsed.email;
            // Re-sync across all 3 storage layers so refresh never loses session
            try { localStorage.setItem('careerpulse_oauth_session', raw); } catch (e) {}
            try { sessionStorage.setItem('careerpulse_oauth_session', raw); } catch (e) {}
            setCookieVal('cp_oauth_session', raw, 30);
            updateAuthBadge();
            return true;
          }
        }
      } catch (e) {}
      updateAuthBadge();
      return false;
    }

    function updateAuthBadge() {
      const area = document.getElementById('auth-badge-area');
      if (!area) return;
      if (STATE.authenticated) {
        area.innerHTML = `<span class="badge b-emerald">🔓 ${escHtml(STATE.userEmail)}</span> <button class="btn btn-sm btn-rose" onclick="signOutOwner()">Logout</button>`;
      } else {
        area.innerHTML = `<button class="btn btn-primary btn-sm" onclick="openOAuthModal()">Login</button>`;
      }
    }

    function handleTopModeSelect(val) {
      if (val === 'studio') openOwnerStudio();
      else setAppMode('academy');
    }

    function setAppMode(mode) {
      const pubEl = document.getElementById('public-academy-view');
      const cmdEl = document.getElementById('owner-command-center');
      const topSel = document.getElementById('top-mode-select');
      if (mode === 'academy') {
        STATE.appMode = 'academy';
        if (pubEl) pubEl.style.display = 'block';
        if (cmdEl) cmdEl.style.display = 'none';
        if (topSel) topSel.value = 'academy';
        saveUiState();
      } else {
        if (!STATE.authenticated && !checkSavedSession()) {
          if (topSel) topSel.value = 'academy';
          openOAuthModal();
          return;
        }
        STATE.appMode = 'studio';
        closeOAuthModal();
        if (pubEl) pubEl.style.display = 'none';
        if (cmdEl) cmdEl.style.display = 'block';
        if (topSel) topSel.value = 'studio';
        switchCmdTab(STATE.cmdTab || 'analytics', true);
        saveUiState();
        if (!STATE.jobs || STATE.jobs.length === 0) {
          Promise.resolve().then(() => loadLiveDashboardData(false));
        }
      }
    }

    function openOwnerStudio() {
      if (STATE.authenticated || checkSavedSession()) {
        closeOAuthModal();
        setAppMode('studio');
      } else {
        openOAuthModal();
      }
    }

    function openOAuthModal() {
      const m = document.getElementById('oauth-modal');
      if (m) m.style.display = 'flex';
    }

    function closeOAuthModal() {
      const m = document.getElementById('oauth-modal');
      if (m) m.style.display = 'none';
      const st = document.getElementById('oauth-status-msg');
      if (st) st.textContent = '';
    }

    async function handleGoogleJwtResponse(response) {
      const statusEl = document.getElementById('oauth-status-msg');
      if (statusEl) statusEl.textContent = 'Verifying Google OAuth JWT token...';
      try {
        const res = await fetch(`${AUTH_URL}?action=verify_google_jwt&credential=${encodeURIComponent(response.credential)}`);
        const data = await res.json();
        if (data.status === 'AUTHENTICATED') {
          completeLogin(data.email, data.session_token);
        } else if (statusEl) {
          statusEl.textContent = data.message || 'OAuth verification failed.';
        }
      } catch (e) {
        if (statusEl) statusEl.textContent = 'Error verifying token: ' + e.message;
      }
    }

    async function sendTelegramOtp() {
      const email = (document.getElementById('oauth-email-input')?.value || '').trim();
      const statusEl = document.getElementById('oauth-status-msg');
      if (!email) {
        if (statusEl) { statusEl.style.color = '#fb7185'; statusEl.textContent = 'Please enter your email first.'; }
        return;
      }
      if (statusEl) {
        statusEl.style.color = '#38bdf8';
        statusEl.textContent = 'Sending verification code...';
      }
      try {
        const res = await fetch(`${AUTH_URL}?action=send_login_otp&email=${encodeURIComponent(email)}`);
        const data = await res.json();
        if (statusEl) {
          statusEl.style.color = data.status === 'OTP_SENT' ? '#34d399' : '#fb7185';
          statusEl.textContent = data.message || 'Verification code sent.';
        }
      } catch (e) {
        if (statusEl) {
          statusEl.style.color = '#fb7185';
          statusEl.textContent = 'Error sending code: ' + e.message;
        }
      }
    }

    async function verifyOwnerCode() {
      const email = (document.getElementById('oauth-email-input')?.value || '').trim();
      const code = (document.getElementById('oauth-code-input')?.value || '').trim();
      const statusEl = document.getElementById('oauth-status-msg');
      if (!email || !code) {
        if (statusEl) { statusEl.style.color = '#fb7185'; statusEl.textContent = 'Please enter your email and verification code.'; }
        return;
      }
      if (statusEl) {
        statusEl.style.color = '#38bdf8';
        statusEl.textContent = 'Logging in...';
      }
      try {
        const res = await fetch(`${AUTH_URL}?action=verify_login_code&email=${encodeURIComponent(email)}&code=${encodeURIComponent(code)}`);
        const data = await res.json();
        if (data.status === 'AUTHENTICATED') {
          completeLogin(data.email, data.session_token);
        } else if (statusEl) {
          statusEl.style.color = '#fb7185';
          statusEl.textContent = data.message || 'Invalid verification code.';
        }
      } catch (e) {
        if (statusEl) {
          statusEl.style.color = '#fb7185';
          statusEl.textContent = 'Login failed: ' + e.message;
        }
      }
    }

    function completeLogin(email, token) {
      STATE.authenticated = true;
      STATE.userEmail = email || 'user@example.com';
      const sessRaw = JSON.stringify({ email: STATE.userEmail, token: token || ('SESSION_' + Date.now()), ts: Date.now() });
      try { localStorage.setItem('careerpulse_oauth_session', sessRaw); } catch (e) {}
      try { sessionStorage.setItem('careerpulse_oauth_session', sessRaw); } catch (e) {}
      setCookieVal('cp_oauth_session', sessRaw, 30);
      closeOAuthModal();
      updateAuthBadge();
      setAppMode('studio');
      callApi({
        action: 'save_session_state',
        authenticated: true,
        email: STATE.userEmail,
        uiState: {
          appMode: STATE.appMode || 'studio',
          cmdTab: STATE.cmdTab || 'analytics',
          selectedSno: STATE.selectedSno || '1',
          studioBucketFilter: STATE.studioBucketFilter || 'ALL',
          previewDoc: STATE.previewDoc || 'resume',
          previewMode: STATE.previewMode || 'sheet'
        }
      }).catch(() => {});
      showToast('Logged in — Welcome Sumanto!', '#10b981');
    }

    function signOutOwner() {
      STATE.authenticated = false;
      STATE.userEmail = '';
      try { localStorage.removeItem('careerpulse_oauth_session'); } catch (e) {}
      try { sessionStorage.removeItem('careerpulse_oauth_session'); } catch (e) {}
      setCookieVal('cp_oauth_session', '', -1);
      callApi({ action: 'save_session_state', authenticated: false }).catch(() => {});
      updateAuthBadge();
      setAppMode('academy');
      showToast('Logged out.', '#f59e0b');
    }

    // ============================================================================
    // API HELPER & LIVE DASHBOARD SYNC
    // ============================================================================
    async function callApi(payload) {
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error('API HTTP ' + res.status);
      return await res.json();
    }

    async function loadLiveDashboardData(showToastFlag = true) {
      if (showToastFlag) showToast('Syncing live Google Sheets & Hostinger Postgres...', '#38bdf8');
      try {
        const data = await callApi({ action: 'load_data' });
        applyApiPayload(data);
        if (showToastFlag) showToast(`Synced ${STATE.jobs.length} jobs, ${STATE.learnedRules.length} rules & ${STATE.liLogs.length} LinkedIn items!`, '#10b981');
      } catch (e) {
        showToast('Sync error: ' + e.message, '#f43f5e');
      }
    }

    function applyApiPayload(data) {
      if (!data) return;
      STATE.jobs = Array.isArray(data.jobs) ? data.jobs : [];
      STATE.counts = data.counts || {};
      STATE.byPortal = data.byPortal || {};
      STATE.byCategory = data.byCategory || {};
      STATE.learnedRules = Array.isArray(data.learnedRules) ? data.learnedRules : [];
      STATE.liLogs = Array.isArray(data.liLogs) ? data.liLogs : [];
      STATE.fhContacts = Array.isArray(data.fhContacts) ? data.fhContacts : [];
      STATE.liStats = data.liStats || {};
      STATE.vaultRows = Array.isArray(data.vaultRows) ? data.vaultRows : [];
      STATE.socialSsoRows = Array.isArray(data.socialSsoRows) ? data.socialSsoRows : [];
      STATE.limitRows = Array.isArray(data.limitRows) ? data.limitRows : [];
      STATE.masterResume = data.masterResume || {};

      const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
      setTxt('kpi-total', STATE.counts.total ?? STATE.jobs.length);
      setTxt('kpi-pending', STATE.counts.pendingReview ?? 0);
      setTxt('kpi-approved', STATE.counts.approvedQueued ?? 0);
      setTxt('kpi-applied', STATE.counts.applied ?? 0);
      setTxt('kpi-interviewing', (STATE.counts.interviewing ?? 0) + (STATE.counts.offer ?? 0));
      setTxt('kpi-rejected', STATE.counts.rejected ?? 0);
      setTxt('kpi-network', STATE.liLogs.length + STATE.fhContacts.length);
      setTxt('kpi-network-sub', `${STATE.liLogs.length} Posts • ${STATE.fhContacts.length} Contacts`);

      populatePortalFilterDropdown();
      populateStudioJobDropdown();
      renderStudioLeft();
      renderStudioRight();
      renderMasterTable();
      renderAnalyticsCharts();
      renderLinkedInView();
      renderNetworkView();
      renderRulesAndPortalsView();
    }

    function switchCmdTab(tabName, skipSave = false) {
      STATE.cmdTab = tabName || 'analytics';
      const viewSel = document.getElementById('cmd-view-select');
      if (viewSel) viewSel.value = STATE.cmdTab;
      ['studio', 'table', 'analytics', 'linkedin', 'network', 'rules'].forEach(t => {
        const el = document.getElementById('cmd-view-' + t);
        if (el) el.style.display = (t === STATE.cmdTab) ? 'block' : 'none';
      });
      if (!skipSave) saveUiState();
    }

    function runGlobalMenuAction() {
      const act = document.getElementById('cmd-global-action-select')?.value || 'refresh';
      if (act === 'refresh') loadLiveDashboardData(true);
      else if (act === 'gen25') triggerGenerateNewJobs();
      else if (act === 'wf6') triggerWorkflow('wf6');
      else if (act === 'wf7') triggerWorkflow('wf7');
      else if (act === 'edit_html') openHtmlEditorModal();
    }

    function filterByBucket(bucket) {
      STATE.studioBucketFilter = bucket;
      const sel = document.getElementById('studio-bucket-filter');
      if (sel) sel.value = bucket;
      const tblSel = document.getElementById('tbl-stage-filter');
      if (tblSel) tblSel.value = bucket;
      populateStudioJobDropdown();
      renderStudioLeft();
      renderStudioRight();
      renderMasterTable();
      saveUiState();
    }

    // ============================================================================
    // SPLIT-SCREEN STUDIO (LEFT DETAILS/JD/DROPDOWN + RIGHT EMBEDDED RESUME / CL)
    // ============================================================================
    function getFilteredStudioJobs() {
      const f = STATE.studioBucketFilter || 'ALL';
      const base = (f === 'ALL') ? [...(STATE.jobs || [])] : (STATE.jobs || []).filter(j => j.stageBucket === f);
      return base.sort((a, b) => (Number(b.sNoNum ?? b.sNo) || 0) - (Number(a.sNoNum ?? a.sNo) || 0));
    }

    function populateStudioJobDropdown() {
      const sel = document.getElementById('studio-job-select');
      if (!sel) return;
      const list = getFilteredStudioJobs();
      if (list.length === 0) {
        sel.innerHTML = `<option value="">No jobs in stage (${escHtml(STATE.studioBucketFilter)})</option>`;
        return;
      }
      if (!list.some(j => String(j.sNo) === String(STATE.selectedSno))) {
        STATE.selectedSno = String(list[0].sNo);
      }
      sel.innerHTML = list.map(j => {
        const clTag = (j.clDriveId || j.clSections?.hasStoredCl) ? ' ✉️' : '';
        return `<option value="${escHtml(j.sNo)}" ${String(j.sNo) === String(STATE.selectedSno) ? 'selected' : ''}>#${escHtml(j.sNo)} (${escHtml(j.resumeId)}) — ${escHtml(j.company)} | ${escHtml(j.title)} [${escHtml(j.stageBucket)}]${clTag}</option>`;
      }).join('');
    }

    function applyStudioBucketFilter(bucket) {
      STATE.studioBucketFilter = bucket;
      populateStudioJobDropdown();
      renderStudioLeft();
      renderStudioRight();
      saveUiState();
    }

    function selectJobBySno(sNo) {
      STATE.selectedSno = String(sNo);
      const sel = document.getElementById('studio-job-select');
      if (sel) sel.value = STATE.selectedSno;
      renderStudioLeft();
      renderStudioRight();
      renderMasterTable();
      saveUiState();
    }

    function stepJob(delta) {
      const list = getFilteredStudioJobs();
      if (!list.length) return;
      const idx = list.findIndex(j => String(j.sNo) === String(STATE.selectedSno));
      const nextIdx = Math.max(0, Math.min(list.length - 1, (idx === -1 ? 0 : idx) + delta));
      selectJobBySno(list[nextIdx].sNo);
    }

    function getCurrentJob() {
      return STATE.jobs.find(j => String(j.sNo) === String(STATE.selectedSno)) || STATE.jobs[0] || null;
    }

    function stageBadgeHtml(bucket) {
      const b = String(bucket || 'Pending Review');
      if (b === 'Applied') return `<span class="badge b-sky">📤 Applied</span>`;
      if (b === 'Interviewing' || b === 'Offer') return `<span class="badge b-purple">🎯 ${escHtml(b)}</span>`;
      if (b === 'Approved / Queued') return `<span class="badge b-emerald">✅ Approved / Queued</span>`;
      if (b === 'Rejected') return `<span class="badge b-rose">❌ Rejected</span>`;
      if (b === 'Needs Rework') return `<span class="badge b-amber">🛠️ Needs Rework</span>`;
      return `<span class="badge b-amber">⏳ ${escHtml(b)}</span>`;
    }

    function runSelectedStudioAction() {
      const val = document.getElementById('studio-action-select')?.value || 'apr_res';
      if (val === 'edit_html') {
        openHtmlEditorModal();
      } else if (val.startsWith('stage:')) {
        quickStageUpdate(val.slice('stage:'.length));
      } else {
        quickJobAction(val);
      }
    }

    function renderStudioLeft() {
      const box = document.getElementById('studio-left-body');
      if (!box) return;
      const j = getCurrentJob();
      if (!j) {
        box.innerHTML = `<div style="padding:24px; color:var(--muted); text-align:center;">No jobs loaded yet. Select <b>🔄 Refresh Live Data</b> above.</div>`;
        return;
      }

      const isClMode = STATE.previewDoc === 'cl';
      box.innerHTML = `
        <div style="background:#090f1d; border:1px solid var(--border-hi); border-radius:12px; padding:13px;">
          <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px; flex-wrap:wrap; margin-bottom:6px;">
            <div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap;">
              <span class="badge b-sky mono">#${escHtml(j.sNo)} • ${escHtml(j.resumeId)}</span>
              ${stageBadgeHtml(j.stageBucket)}
              <span class="badge b-purple">${escHtml(j.portal)}</span>
            </div>
            ${j.jdUrl ? `<a href="${escHtml(j.jdUrl)}" target="_blank" class="btn btn-sm">🔗 Job Posting ↗</a>` : ''}
          </div>
          <div style="font-size:17px; font-weight:800; color:#f8fafc;">${escHtml(j.title)}</div>
          <div style="font-size:13px; color:#38bdf8; font-weight:700; margin-top:2px;">${escHtml(j.company)} <span style="color:var(--muted); font-weight:500;">• ${escHtml(j.location)} • ${escHtml(j.roleCategory)}</span></div>
          <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap:6px; margin-top:10px; font-size:11px; background:#060a14; padding:8px; border-radius:8px; border:1px solid var(--border);">
            <div><span style="color:var(--muted);">Created On:</span><br><b class="mono">${escHtml(j.createdOn || '—')}</b></div>
            <div><span style="color:var(--muted);">Last Updated:</span><br><b class="mono" style="color:#38bdf8;">${escHtml(j.lastUpdated || '—')}</b></div>
            <div><span style="color:var(--muted);">Applied On:</span><br><b class="mono" style="color:#34d399;">${escHtml(j.appliedOn || '—')}</b></div>
            <div><span style="color:var(--muted);">Resume / CL:</span><br><b>${escHtml(j.resumeStatus || 'Pending')} / ${escHtml(j.clStatus || '—')}</b></div>
          </div>
        </div>

        <div style="background:#090f1d; border:1px solid var(--border-hi); border-radius:12px; padding:12px;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
            <span style="font-size:11.5px; font-weight:800; color:#38bdf8; text-transform:uppercase;">📋 Job Description & Target Keywords</span>
            <span class="badge b-emerald">80% Grounded / 20% JD Lens</span>
          </div>
          ${j.extractedKeywords ? `<div style="margin-bottom:8px; font-size:11.5px; color:#7dd3fc; background:#060a14; padding:7px 9px; border-radius:8px; border:1px solid rgba(56,189,248,0.25);"><b>Target JD Keywords:</b> ${escHtml(j.extractedKeywords)}</div>` : ''}
          <div style="max-height:210px; overflow-y:auto; font-size:12.5px; color:#e2e8f0; white-space:pre-wrap; line-height:1.55; padding:10px; background:#060a14; border-radius:8px; border:1px solid var(--border);">${escHtml(j.jd || 'No detailed Job Description stored for this posting.')}</div>
        </div>

        <div style="background:#090f1d; border:1px solid var(--border); border-radius:12px; padding:12px;">
          <label class="field-label" style="margin-bottom:6px;">⚡ Select Action or Pipeline Stage</label>
          <div style="display:flex; gap:8px; align-items:center;">
            <select id="studio-action-select" style="flex:1; font-weight:700;">
              <option value="apr_res">✅ Approve Resume (LGTM — Queue Auto-Apply)</option>
              <option value="apr_res_cl">✨ Approve Resume + Create Cover Letter (WF3)</option>
              <option value="generate_cl">✉️ Generate / Refresh 1-Page Cover Letter (WF3)</option>
              <option value="apr_cl">✅ Approve Cover Letter (LGTM)</option>
              <option value="stage:Applied">📤 Mark Status: Applied</option>
              <option value="stage:Interviewing">🎯 Mark Status: Interviewing</option>
              <option value="stage:Offer Received">🏆 Mark Status: Offer Received</option>
              <option value="stage:Rejected">❌ Mark Status: Rejected</option>
              <option value="stage:Skipped / Hold">⏸️ Mark Status: Hold / Skip</option>
              <option value="stage:Pending Review">⏳ Reset Status: Pending Review</option>
              <option value="edit_html">✏️ Open Direct HTML Section Editor</option>
            </select>
            <button class="btn btn-primary" onclick="runSelectedStudioAction()">Apply</button>
          </div>
        </div>

        <div style="background:linear-gradient(180deg, rgba(14,165,233,0.09), rgba(99,102,241,0.06)); border:1px solid rgba(56,189,248,0.35); border-radius:12px; padding:12px;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:11.5px; font-weight:800; color:#38bdf8; text-transform:uppercase;">✍️ Feedback & Self-Learning Rewriter (WF2 / WF3)</span>
