    function initFhPrefs() {
      if (!STATE.fhPrefs) {
        STATE.fhPrefs = {
          cat: 'ALL',
          domain: 'ALL',
          loc: 'ALL',
          stage: 'ALL',
          search: '',
          sortBy: 'starred_first',
          templateMode: 'SAVED',
          onlyActiveJobCompanies: false
        };
      }
      return STATE.fhPrefs;
    }

    function filterFhTable(cat) {
      const p = initFhPrefs();
      p.cat = cat;
      renderNetworkView();
    }

    function setFhPref(key, val) {
      const p = initFhPrefs();
      p[key] = val;
      renderNetworkView();
    }

    function resetFhPrefs() {
      STATE.fhPrefs = {
        cat: 'ALL', domain: 'ALL', loc: 'ALL', stage: 'ALL',
        search: '', sortBy: 'starred_first', templateMode: 'SAVED', onlyActiveJobCompanies: false
      };
      renderNetworkView();
    }

    function classifyFhCategory(c) {
      const raw = (String(c.category || '') + ' ' + String(c.role_title || '')).toUpperCase();
      if (raw.includes('REFERRAL') || raw.includes('INSIDER')) return 'INSIDER';
      if (raw.includes('HIRING MANAGER') || raw.includes('PARTNER') || raw.includes('CO-FOUNDER') || raw.includes('CHIEF') || raw.includes('OFFICER')) return 'MANAGER';
      if (raw.includes('HR') || raw.includes('TALENT') || raw.includes('RECRUIT')) return 'HR';
      return 'PEER';
    }

    function classifyFhDomain(c) {
      const txt = (String(c.company_name || '') + ' ' + String(c.notes_log || '') + ' ' + String(c.role_title || '')).toUpperCase();
      if (/CITI|BLACKROCK|MASTERCARD|AMERICAN EXPRESS|AMEX|GOLDMAN|STRIPE|RAZORPAY|PAYPAL|UBS|BARCLAYS|VISA|PHONEPE|CRED|HDFC|FINTECH|BANKING|WEALTH/.test(txt)) return 'FINTECH';
      if (/MCKINSEY|BCG|BAIN|DELOITTE|EY|PWC|KPMG|FRACTAL|TIGER ANALYTICS|AXTRIA|NAGARRO|CONSULT/.test(txt)) return 'CONSULTING';
      if (/SWIGGY|FLIPKART|MEESHO|CARS24|TARGET|NIELSEN|KMART|ZOMATO|BLINKIT|RETAIL|ECOMMERCE/.test(txt)) return 'ECOM';
      return 'TECH';
    }

    function classifyFhLoc(c) {
      const loc = String(c.location || '').toUpperCase();
      if (/GURUGRAM|GURGAON|NOIDA|DELHI|NCR/.test(loc)) return 'NCR';
      if (/BENGALURU|BANGALORE/.test(loc)) return 'BLR';
      if (/MUMBAI|PUNE/.test(loc)) return 'MUM_PUN';
      if (/HYDERABAD|CHENNAI/.test(loc)) return 'HYD_CHE';
      return 'INTL';
    }

    function isFhStarred(c) {
      return String(c.notes_log || '').includes('[STARRED]');
    }

    function getCompanyMatchingJobs(compName) {
      const raw = String(compName || '').toLowerCase().split('/')[0].split('(')[0].trim();
      if (!raw || raw.length < 2) return [];
      return (STATE.jobs || []).filter(j => {
        const jc = String(j.company || '').toLowerCase();
        return jc && (jc.includes(raw) || raw.includes(jc));
      });
    }

    function buildReachOutNote(c, mode) {
      const first = String(c.person_name || 'there').split(' ')[0];
      const comp = String(c.company_name || 'your company').split('/')[0].trim();
      const matchedJobs = getCompanyMatchingJobs(comp);
      const roleTitle = matchedJobs.length > 0 ? matchedJobs[0].job_title : 'Senior Data & Business Analyst';
      if (mode === 'REFERRAL') {
        return `Hi ${first}, applying for ${roleTitle} at ${comp}—would love your quick take or a referral if my background fits!`;
      }
      if (mode === 'RECRUITER_RADAR') {
        return `Hi ${first}, closely following ${comp}'s analytics hiring—would love to connect and stay on your radar!`;
      }
      if (mode === 'PEER_WARM') {
        return `Hi ${first}, great seeing your analytics work at ${comp}—would love to connect!`;
      }
      if (mode === 'COFFEE_CHAT') {
        return `Hi ${first}, admire your analytics journey at ${comp}—would love to connect and swap notes sometime!`;
      }
      return String(c.connection_note || '');
    }

    async function promptEditFhNote(contactId) {
      const c = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!c) return;
      const updated = window.prompt(`Edit saved reach-out note for ${c.person_name} (${c.company_name}):`, c.connection_note || '');
      if (updated === null) return;
      try {
        const res = await callApi({ action: 'fh_action', contactId, subAction: 'edit', connectionNote: updated });
        applyApiPayload(res);
        showToast(res.message || 'Saved custom reach-out note!', '#10b981');
      } catch (e) {
        showToast('Error saving note: ' + e.message, '#f43f5e');
      }
    }

    function hasInboundReply(c) {
      const msgs = Array.isArray(c.messages) ? c.messages : [];
      return msgs.some(m => m.sender === 'them' && !String(m.text || '').startsWith('[LinkedIn Post]') && !String(m.text || '').startsWith('[LinkedIn Pulse]') && !String(m.text || '').startsWith('[Activity Context]'));
    }

    function hasAnyMemberMsg(c) {
      const msgs = Array.isArray(c.messages) ? c.messages : [];
      return msgs.some(m => m.sender === 'them');
    }

    function fillSmartFhReply(contactId) {
      const c = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!c) return;
      const inp = document.getElementById('fh-reply-inp-' + contactId);
      if (!inp) return;
      const p = initFhPrefs();
      const first = String(c.person_name || 'there').split(' ')[0];
      const comp = String(c.company_name || 'your team').split('/')[0].trim();
      const matchedJobs = getCompanyMatchingJobs(comp);
      const jobTitle = matchedJobs.length > 0 ? matchedJobs[0].job_title : 'Senior Data & Business Analyst';
      const msgs = Array.isArray(c.messages) ? c.messages : [];
      const lastThem = [...msgs].reverse().find(m => m.sender === 'them');

      if (p.templateMode !== 'SAVED') {
        inp.value = buildReachOutNote(c, p.templateMode);
      } else if (lastThem && /requisition|job id|apply|flag|cv|resume|openings/i.test(lastThem.text || '')) {
        inp.value = `Thanks so much, ${first}! I've prepared my tailored application for the ${jobTitle} role at ${comp}—sharing my resume and details right away. Really appreciate your support!`;
      } else if (lastThem && /post|pulse|metric|ai|model/i.test(lastThem.text || '')) {
        inp.value = `Hi ${first}, really enjoyed your recent post on this topic! I work in SQL, Python, and Tableau analytics and would love to stay connected and exchange notes regarding ${comp}.`;
      } else {
        inp.value = buildReachOutNote(c, matchedJobs.length > 0 ? 'REFERRAL' : 'SAVED');
      }
      inp.focus();
      showToast('Drafted smart reply for ' + c.person_name + ' — review & click Send!', '#38bdf8');
    }

    async function sendFhReply(contactId) {
      const c = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!c) return;
      const inp = document.getElementById('fh-reply-inp-' + contactId);
      const replyText = (inp ? inp.value : '').trim();
      if (!replyText) {
        showToast('Type a reply message first (or click ⚡ Smart Draft).', '#f59e0b');
        return;
      }
      try { navigator.clipboard.writeText(replyText); } catch (e) {}
      if (inp) inp.disabled = true;
      showToast('📨 Workflow sending reply to ' + c.person_name + ' on LinkedIn...', '#38bdf8');
      try {
        const res = await callApi({
          action: 'fh_action',
          subAction: 'send_reply',
          contactId,
          replyText,
          senderRole: 'me'
        });
        if (inp) { inp.value = ''; inp.disabled = false; }
        applyApiPayload(res);
        showToast(res.message || 'Reply processed by workflow!', '#10b981');
        setTimeout(() => {
          const box = document.getElementById('fh-msg-box-' + contactId);
          if (box) box.scrollTop = box.scrollHeight;
        }, 60);
      } catch (e) {
        if (inp) inp.disabled = false;
        showToast('Error sending reply: ' + e.message, '#f43f5e');
      }
    }

    async function logInboundFhMessage(contactId) {
      const c = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!c) return;
      const txt = window.prompt(`Paste or log a message received from ${c.person_name} (${c.company_name}):`, '');
      if (!txt || !txt.trim()) return;
