    function exportFhDirectoryCsv() {
      const rows = window._lastRenderedFhRows || STATE.fhContacts || [];
      const p = initFhPrefs();
      const headers = ['Contact ID', 'Starred', 'Category', 'Domain', 'Company', 'Person Name', 'LinkedIn Profile URL', 'Role Title', 'Location', 'Outreach Stage', 'Approval Status', 'Reach-Out Note'];
      const csvLines = [headers.join(',')];
      for (const c of rows) {
        const vals = [
          c.contact_id,
          isFhStarred(c) ? 'STARRED' : '',
          c.category,
          classifyFhDomain(c),
          c.company_name,
          c.person_name,
          c.target_profile_url,
          c.role_title,
          c.location,
          c.outreach_stage,
          c.approval_status,
          buildReachOutNote(c, p.templateMode)
        ].map(v => `"${String(v || '').replace(/"/g, '""')}"`);
        csvLines.push(vals.join(','));
      }
      const blob = new Blob([csvLines.join('\n')], { type: 'text/csv;charset=utf-8;' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `linkedin_people_directory_${new Date().toISOString().slice(0,10)}.csv`;
      a.click();
      showToast(`Exported ${rows.length} LinkedIn contacts to CSV!`, '#10b981');
    }

    function renderNetworkView() {
      const tbody = document.getElementById('fh-table-tbody');
      if (!tbody) return;
      const p = initFhPrefs();
      const all = STATE.fhContacts || [];

      const totalCount = all.length;
      const starredCount = all.filter(c => isFhStarred(c)).length;
      const hrCount = all.filter(c => classifyFhCategory(c) === 'HR').length;
      const mgrCount = all.filter(c => ['MANAGER', 'INSIDER'].includes(classifyFhCategory(c))).length;
      const peerCount = all.filter(c => classifyFhCategory(c) === 'PEER').length;
      const jobMatchCount = all.filter(c => getCompanyMatchingJobs(c.company_name).length > 0).length;
      const activeThreadsCount = all.filter(c => hasAnyMemberMsg(c)).length;

      const kpiStrip = document.getElementById('fh-kpi-strip');
      if (kpiStrip) {
        const kpiCard = (label, count, sub, active, onClickJs, borderCol) => `
          <div onclick="${onClickJs}" style="cursor:pointer; background:${active ? 'rgba(56,189,248,0.14)' : '#090f1d'}; border:1px solid ${active ? borderCol : 'var(--border)'}; border-radius:10px; padding:10px 12px; transition:all 0.15s;">
            <div style="font-size:11px; color:var(--muted); font-weight:600;">${label}</div>
            <div style="font-size:20px; font-weight:800; color:#f8fafc; margin-top:2px;">${count}</div>
            <div style="font-size:10.5px; color:${borderCol}; margin-top:2px;">${sub}</div>
          </div>`;
        kpiStrip.innerHTML = [
          kpiCard('👥 All LinkedIn People', totalCount, '100% Direct /in/ Profiles', p.cat === 'ALL' && !p.onlyActiveJobCompanies, "setFhPref('onlyActiveJobCompanies', false); setFhPref('cat', 'ALL')", '#38bdf8'),
          kpiCard('⭐ Priority / Starred', starredCount, 'Click to filter top targets', p.cat === 'STARRED', "setFhPref('cat', STATE.fhPrefs.cat==='STARRED'?'ALL':'STARRED')", '#f59e0b'),
          kpiCard('🎯 HR & Tech Recruiters', hrCount, 'Talent Acquisition leads', p.cat === 'HR', "setFhPref('cat', STATE.fhPrefs.cat==='HR'?'ALL':'HR')", '#fbbf24'),
          kpiCard('👔 Leaders & Insiders', mgrCount, 'Partners, Managers & Referrers', p.cat === 'MANAGER_INSIDER', "setFhPref('cat', STATE.fhPrefs.cat==='MANAGER_INSIDER'?'ALL':'MANAGER_INSIDER')", '#a855f7'),
          kpiCard('🤝 Data & BI Peers', peerCount, 'Senior Analysts & Scientists', p.cat === 'PEER', "setFhPref('cat', STATE.fhPrefs.cat==='PEER'?'ALL':'PEER')", '#10b981'),
          kpiCard('💬 Member Threads', activeThreadsCount, 'Click for active replies/posts', p.cat === 'THREADS', "setFhPref('cat', STATE.fhPrefs.cat==='THREADS'?'ALL':'THREADS')", '#34d399'),
          kpiCard('🎯 Active Job Matches', jobMatchCount, 'At companies in Job Tracker', p.onlyActiveJobCompanies, "setFhPref('onlyActiveJobCompanies', !STATE.fhPrefs.onlyActiveJobCompanies)", '#ec4899')
        ].join('');
      }

      const filtered = all.filter(c => {
        const catCode = classifyFhCategory(c);
        if (p.cat === 'STARRED' && !isFhStarred(c)) return false;
        if (p.cat === 'THREADS' && !hasAnyMemberMsg(c)) return false;
        if (p.cat === 'HR' && catCode !== 'HR') return false;
        if (p.cat === 'PEER' && catCode !== 'PEER') return false;
        if (p.cat === 'MANAGER_INSIDER' && !['MANAGER', 'INSIDER'].includes(catCode)) return false;
        if (p.cat === 'INSIDER' && catCode !== 'INSIDER') return false;
        if (p.domain !== 'ALL' && classifyFhDomain(c) !== p.domain) return false;
        if (p.loc !== 'ALL' && classifyFhLoc(c) !== p.loc) return false;
        if (p.onlyActiveJobCompanies && getCompanyMatchingJobs(c.company_name).length === 0) return false;
        if (p.stage !== 'ALL') {
          const st = (String(c.approval_status || '') + ' ' + String(c.execution_status || '') + ' ' + String(c.outreach_stage || '')).toUpperCase();
          if (p.stage === 'SENT' && !/CONFIRMED|SENT|CONNECTED/.test(st)) return false;
          if (p.stage === 'APPROVED' && (!/APPROVED/.test(st) || /CONFIRMED/.test(st))) return false;
          if (p.stage === 'READY' && /CONFIRMED/.test(st)) return false;
        }
        if (p.search && p.search.trim()) {
          const q = p.search.trim().toLowerCase();
          const hay = `${c.contact_id} ${c.person_name} ${c.company_name} ${c.role_title} ${c.location} ${c.category} ${c.notes_log}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });

      const catRank = { 'INSIDER': 1, 'HR': 2, 'MANAGER': 3, 'PEER': 4 };
      const locRank = { 'NCR': 1, 'BLR': 2, 'MUM_PUN': 3, 'HYD_CHE': 4, 'INTL': 5 };

      filtered.sort((a, b) => {
        const numA = parseInt(String(a.contact_id || '').replace(/[^0-9]/g, ''), 10) || 0;
        const numB = parseInt(String(b.contact_id || '').replace(/[^0-9]/g, ''), 10) || 0;
        if (p.sortBy === 'replies_first') {
          const rA = hasInboundReply(a) ? 0 : (hasAnyMemberMsg(a) ? 1 : 2);
          const rB = hasInboundReply(b) ? 0 : (hasAnyMemberMsg(b) ? 1 : 2);
          if (rA !== rB) return rA - rB;
          return (isFhStarred(a) ? 0 : 1) - (isFhStarred(b) ? 0 : 1);
        }
        if (p.sortBy === 'starred_first') {
          const sA = isFhStarred(a) ? 0 : 1;
          const sB = isFhStarred(b) ? 0 : 1;
          if (sA !== sB) return sA - sB;
          const jA = getCompanyMatchingJobs(a.company_name).length;
          const jB = getCompanyMatchingJobs(b.company_name).length;
          if (jA !== jB) return jB - jA;
          return numB - numA;
        }
        if (p.sortBy === 'active_jobs_first') {
          const jA = getCompanyMatchingJobs(a.company_name).length;
          const jB = getCompanyMatchingJobs(b.company_name).length;
          if (jA !== jB) return jB - jA;
          return (isFhStarred(a) ? 0 : 1) - (isFhStarred(b) ? 0 : 1);
        }
        if (p.sortBy === 'company_asc') return String(a.company_name || '').localeCompare(String(b.company_name || ''));
        if (p.sortBy === 'person_asc') return String(a.person_name || '').localeCompare(String(b.person_name || ''));
        if (p.sortBy === 'category_hr_first') {
          const rA = catRank[classifyFhCategory(a)] || 9;
          const rB = catRank[classifyFhCategory(b)] || 9;
          if (rA !== rB) return rA - rB;
          return String(a.company_name || '').localeCompare(String(b.company_name || ''));
        }
        if (p.sortBy === 'location_ncr_first') {
          const lA = locRank[classifyFhLoc(a)] || 9;
          const lB = locRank[classifyFhLoc(b)] || 9;
          if (lA !== lB) return lA - lB;
          return String(a.company_name || '').localeCompare(String(b.company_name || ''));
        }
        if (p.sortBy === 'stage_ready_first') {
          const sentA = /CONFIRMED/i.test(String(a.execution_status || '')) ? 1 : 0;
          const sentB = /CONFIRMED/i.test(String(b.execution_status || '')) ? 1 : 0;
          if (sentA !== sentB) return sentA - sentB;
          return (isFhStarred(a) ? 0 : 1) - (isFhStarred(b) ? 0 : 1);
        }
        return numB - numA;
      });

      window._lastRenderedFhRows = filtered;

      const tb = document.getElementById('fh-pref-toolbar');
      if (tb) {
        tb.innerHTML = `
