            <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center;">
              <button class="btn btn-sm" style="border-color:${STATE.hasLiCookie ? '#10b981' : '#f59e0b'}; color:${STATE.hasLiCookie ? '#34d399' : '#fbbf24'};" onclick="promptSaveLiCookie()" title="Connect LinkedIn li_at cookie for 100% automatic Voyager API DM sending">${STATE.hasLiCookie ? '🟢 Voyager Auto-Send Active' : '🔑 Set li_at for Auto-Send'}</button>
              <button class="btn btn-sm btn-sky" onclick="syncFhInbox()">🔄 Sync Messages</button>
              <button class="btn btn-sm ${p.onlyActiveJobCompanies ? 'btn-primary' : ''}" onclick="setFhPref('onlyActiveJobCompanies', !STATE.fhPrefs.onlyActiveJobCompanies)">🎯 Match My Active Jobs (${jobMatchCount})</button>
              <button class="btn btn-sm btn-emerald" onclick="const d=document.getElementById('fh-add-drawer'); if(d) d.style.display=d.style.display==='none'?'block':'none';">➕ Add Person</button>
              <button class="btn btn-sm" onclick="exportFhDirectoryCsv()">📥 Export CSV</button>
              <button class="btn btn-sm" onclick="resetFhPrefs()">🔄 Reset</button>
            </div>
          </div>
          <div style="display:grid; grid-template-columns: 1.3fr repeat(5, minmax(140px, 1fr)); gap:8px;">
            <input type="text" id="fh-search-inp" value="${escHtml(p.search)}" placeholder="🔍 Search person, company (BCG, Citi, Amex, Stripe), title, city..." oninput="setFhPref('search', this.value)" />
            <select onchange="setFhPref('sortBy', this.value)" title="Sort By Preference">
              <option value="starred_first" ${p.sortBy==='starred_first'?'selected':''}>🔃 Sort: ⭐ Starred & Job Match First</option>
              <option value="replies_first" ${p.sortBy==='replies_first'?'selected':''}>🔃 Sort: 💬 Member Replies & Active Threads First</option>
              <option value="active_jobs_first" ${p.sortBy==='active_jobs_first'?'selected':''}>🔃 Sort: 🎯 My Active Job Companies First</option>
              <option value="company_asc" ${p.sortBy==='company_asc'?'selected':''}>🔃 Sort: 🏢 Company Name (A → Z)</option>
              <option value="person_asc" ${p.sortBy==='person_asc'?'selected':''}>🔃 Sort: 👤 Person Name (A → Z)</option>
              <option value="category_hr_first" ${p.sortBy==='category_hr_first'?'selected':''}>🔃 Sort: 🎯 Insiders & HR Recruiters First</option>
              <option value="location_ncr_first" ${p.sortBy==='location_ncr_first'?'selected':''}>🔃 Sort: 📍 Gurugram/NCR → BLR → Global</option>
              <option value="stage_ready_first" ${p.sortBy==='stage_ready_first'?'selected':''}>🔃 Sort: 🚀 Ready to Reach Out First</option>
              <option value="newest_first" ${p.sortBy==='newest_first'?'selected':''}>🔃 Sort: 🆕 Recently Added (FH-60 → FH-1)</option>
            </select>
            <select onchange="setFhPref('cat', this.value)" title="Filter by Role Category">
              <option value="ALL" ${p.cat==='ALL'?'selected':''}>🎭 Category: All (${totalCount})</option>
              <option value="STARRED" ${p.cat==='STARRED'?'selected':''}>⭐ Starred Priority (${starredCount})</option>
              <option value="HR" ${p.cat==='HR'?'selected':''}>🎯 HR & Talent Recruiters (${hrCount})</option>
              <option value="MANAGER_INSIDER" ${p.cat==='MANAGER_INSIDER'?'selected':''}>👔 Hiring Managers & Insiders (${mgrCount})</option>
              <option value="PEER" ${p.cat==='PEER'?'selected':''}>🤝 Data & BI Peers (${peerCount})</option>
            </select>
            <select onchange="setFhPref('domain', this.value)" title="Filter by Industry Domain">
              <option value="ALL" ${p.domain==='ALL'?'selected':''}>🏦 Domain: All Industries</option>
              <option value="FINTECH" ${p.domain==='FINTECH'?'selected':''}>🏦 Banking, Fintech & Payments</option>
              <option value="CONSULTING" ${p.domain==='CONSULTING'?'selected':''}>💼 MBB, Big 4 & Analytics Consulting</option>
              <option value="TECH" ${p.domain==='TECH'?'selected':''}>💻 Big Tech, Cloud & SaaS</option>
              <option value="ECOM" ${p.domain==='ECOM'?'selected':''}>🛒 E-Commerce & Consumer Tech</option>
            </select>
            <select onchange="setFhPref('loc', this.value)" title="Filter by Location">
              <option value="ALL" ${p.loc==='ALL'?'selected':''}>🗺️ Location: All Regions</option>
              <option value="NCR" ${p.loc==='NCR'?'selected':''}>📍 Gurugram / Delhi NCR</option>
              <option value="BLR" ${p.loc==='BLR'?'selected':''}>📍 Bengaluru</option>
              <option value="MUM_PUN" ${p.loc==='MUM_PUN'?'selected':''}>📍 Mumbai / Pune</option>
              <option value="HYD_CHE" ${p.loc==='HYD_CHE'?'selected':''}>📍 Hyderabad / Chennai</option>
              <option value="INTL" ${p.loc==='INTL'?'selected':''}>🌍 Europe / Australia / Global</option>
            </select>
            <select onchange="setFhPref('templateMode', this.value)" title="Switch On-Demand Reach-Out Purpose" style="border-color:#38bdf8; font-weight:700;">
              <option value="SAVED" ${p.templateMode==='SAVED'?'selected':''}>💬 Note: Saved Default Icebreaker</option>
              <option value="REFERRAL" ${p.templateMode==='REFERRAL'?'selected':''}>🎯 Note: Ask for Referral (Active Job)</option>
              <option value="RECRUITER_RADAR" ${p.templateMode==='RECRUITER_RADAR'?'selected':''}>📅 Note: Recruiter Radar Check-In</option>
              <option value="PEER_WARM" ${p.templateMode==='PEER_WARM'?'selected':''}>🤝 Note: Warm Peer Connect (No Ask)</option>
              <option value="COFFEE_CHAT" ${p.templateMode==='COFFEE_CHAT'?'selected':''}>☕ Note: 10-Min Insider Coffee Chat</option>
            </select>
          </div>
        `;
      }

      const domLabels = { 'FINTECH': '🏦 Banking & Fintech', 'CONSULTING': '💼 Consulting & Analytics', 'TECH': '💻 Big Tech & SaaS', 'ECOM': '🛒 E-Commerce & Retail' };
      const catBadges = {
        'HR': { label: '🎯 HR / Recruiter', cls: 'b-amber' },
        'INSIDER': { label: '🔑 Referral Insider', cls: 'b-purple' },
        'MANAGER': { label: '👔 Hiring Leader', cls: 'b-sky' },
        'PEER': { label: '🤝 Data & BI Peer', cls: 'b-emerald' }
      };

      tbody.innerHTML = filtered.map(c => {
        const profUrl = (c.target_profile_url && c.target_profile_url.startsWith('http')) ? c.target_profile_url : `https://www.linkedin.com/in/`;
        const postUrl = (c.latest_post_url && c.latest_post_url.startsWith('http')) ? c.latest_post_url : '';
        const starred = isFhStarred(c);
        const catCode = classifyFhCategory(c);
        const catInfo = catBadges[catCode] || catBadges.PEER;
        const domLabel = domLabels[classifyFhDomain(c)] || '💻 Tech';
        const matchedJobs = getCompanyMatchingJobs(c.company_name);
        const activeNote = buildReachOutNote(c, p.templateMode);
        const execTxt = c.execution_status || c.connection_status || 'Awaiting Approval';

        return `
          <tr style="${starred ? 'background:rgba(245,158,11,0.04);' : ''}">
            <td class="mono" style="white-space:nowrap;">
              <button class="btn btn-sm" style="padding:2px 6px; font-size:13px; background:transparent; border:1px solid ${starred ? '#f59e0b' : 'var(--border)'}; color:${starred ? '#fbbf24' : 'var(--muted)'};" onclick="fhItemAction('${escHtml(c.contact_id)}', 'toggle_star')" title="Toggle Priority Star">${starred ? '⭐' : '☆'}</button>
              <b style="margin-left:4px;">${escHtml(c.contact_id)}</b>
            </td>
            <td>
              <span class="badge ${catInfo.cls}">${catInfo.label}</span>
              <div style="font-size:10.5px; color:var(--muted); margin-top:4px;">${domLabel}</div>
            </td>
            <td>
              <div style="font-weight:800; color:#f8fafc;">${escHtml(c.company_name)}</div>
              ${matchedJobs.length > 0 ? `<div style="margin-top:4px;"><span class="badge b-sky" style="cursor:pointer; font-size:10px;" onclick="openJobInStudio(${matchedJobs[0].id})" title="Click to open ${escHtml(matchedJobs[0].job_title)} in Split-Screen Studio">🎯 ${matchedJobs.length} Job${matchedJobs.length>1?'s':''} in Tracker ↗</span></div>` : ''}
            </td>
            <td>
              <div style="font-weight:800; font-size:13px; color:#f8fafc;">${escHtml(c.person_name)}</div>
              <div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:3px;">
                <a href="${escHtml(profUrl)}" target="_blank" style="color:#38bdf8; font-size:11.5px; font-weight:700;">🔗 Open Profile ↗</a>
                ${postUrl ? `<a href="${escHtml(postUrl)}" target="_blank" style="color:#a855f7; font-size:11px; font-weight:600;">📰 Recent Post ↗</a>` : ''}
              </div>
            </td>
            <td>
              <div style="font-size:12px; font-weight:600; color:#e2e8f0;">${escHtml(c.role_title)}</div>
              <div style="font-size:11px; color:var(--muted); margin-top:2px;">📍 ${escHtml(c.location || 'India / Global')}</div>
            </td>
            <td style="min-width:370px; max-width:430px;">
              <div id="fh-msg-box-${escHtml(c.contact_id)}" style="max-height:132px; overflow-y:auto; background:#050913; border:1px solid ${hasInboundReply(c) ? 'rgba(52,211,153,0.45)' : 'var(--border)'}; border-radius:8px; padding:7px 8px; display:flex; flex-direction:column; gap:6px; margin-bottom:6px;">
                ${(Array.isArray(c.messages) && c.messages.length > 0 ? c.messages : [{ sender: 'me', author: 'You (Sumanto)', text: activeNote, ts: 'Draft Ready', channel: 'Outreach Note', status: c.approval_status || 'Ready' }]).map(m => {
                  const isThem = m.sender === 'them';
                  return `
                    <div style="align-self:${isThem ? 'flex-start' : 'flex-end'}; max-width:92%; background:${isThem ? 'rgba(56,189,248,0.12)' : 'rgba(16,185,129,0.12)'}; border:1px solid ${isThem ? 'rgba(56,189,248,0.32)' : 'rgba(16,185,129,0.28)'}; border-radius:8px; padding:5px 8px;">
                      <div style="display:flex; justify-content:space-between; gap:8px; font-size:10px; color:${isThem ? '#38bdf8' : '#34d399'}; font-weight:700; margin-bottom:2px;">
                        <span>${isThem ? '👤 ' + escHtml(c.person_name.split(' ')[0]) : '📤 You'} • ${escHtml(m.channel || 'LinkedIn')}</span>
                        <span style="color:var(--muted); font-weight:500;">${escHtml(m.ts || '')}</span>
                      </div>
                      <div style="font-size:11.5px; line-height:1.38; color:#f1f5f9;">${escHtml(m.text || '')}</div>
                    </div>`;
                }).join('')}
              </div>
              <div style="display:flex; gap:5px; align-items:center;">
                <input type="text" id="fh-reply-inp-${escHtml(c.contact_id)}" placeholder="Reply to ${escHtml(c.person_name.split(' ')[0])}... (Enter to send)" style="flex:1; padding:5px 8px; font-size:11.5px; border-radius:7px; background:#090f1d; border:1px solid var(--border); color:#f8fafc;" onkeydown="if(event.key==='Enter') sendFhReply('${escHtml(c.contact_id)}')" />
                <button class="btn btn-sm" style="padding:4px 7px; font-size:11px;" onclick="fillSmartFhReply('${escHtml(c.contact_id)}')" title="Auto-fill smart context reply or selected template">⚡ Draft</button>
                <button class="btn btn-sm btn-primary" style="padding:4px 9px; font-size:11px; font-weight:700;" onclick="sendFhReply('${escHtml(c.contact_id)}')" title="Send reply via Workflow (Voyager API + Clipboard)">📨 Send</button>
              </div>
            </td>
            <td style="font-size:11.5px;">
              ${hasInboundReply(c) ? '<div style="margin-bottom:4px;"><span class="badge b-emerald" style="font-size:10px;">💬 Member Replied</span></div>' : ''}
              <span class="badge ${/approved|replied/i.test(c.approval_status) ? 'b-emerald' : 'b-amber'}">${escHtml(c.approval_status || 'Ready')}</span>
              <div style="color:#34d399; font-size:11px; margin-top:4px;">${escHtml(execTxt)}</div>
              <div style="color:var(--muted); font-size:10.5px; margin-top:2px;">${escHtml(c.outreach_stage || '')}</div>
            </td>
            <td style="white-space:nowrap;">
              <div style="display:flex; flex-direction:column; gap:4px;">
                <div style="display:flex; gap:4px;">
                  <button class="btn btn-sm" onclick="navigator.clipboard.writeText(${escAttrJson(activeNote)}); showToast('Copied note for ' + ${escAttrJson(c.person_name)} + '!', '#10b981')" title="Copy message">📋 Copy</button>
                  <button class="btn btn-sm" onclick="logInboundFhMessage('${escHtml(c.contact_id)}')" title="Log a message received from ${escHtml(c.person_name)}">📥 +Msg</button>
                </div>
                <div style="display:flex; gap:4px;">
                  <button class="btn btn-sm btn-primary" onclick="fhItemAction('${escHtml(c.contact_id)}', 'approve')">✅ Approve</button>
                  <button class="btn btn-sm btn-emerald" onclick="fhItemAction('${escHtml(c.contact_id)}', 'confirm_sent')">☑️ Sent</button>
                </div>
                <div style="display:flex; gap:4px;">
                  <button class="btn btn-sm" style="border-color:#a855f7; color:#c084fc;" onclick="promptFeedbackFhNote('${escHtml(c.contact_id)}')" title="Rewrite note with LLM feedback & learn rule">💬 Feedback</button>
                  <button class="btn btn-sm" style="border-color:#f43f5e; color:#fb7185;" onclick="fhItemAction('${escHtml(c.contact_id)}', 'skip')" title="Reject / Skip contact">❌ Reject</button>
                </div>
              </div>
            </td>
          </tr>
        `;
      }).join('');

      const searchEl = document.getElementById('fh-search-inp');
      if (searchEl && document.activeElement && document.activeElement.id === 'fh-search-inp') {
        const len = searchEl.value.length;
        searchEl.setSelectionRange(len, len);
      }
    }

    async function promptFeedbackFhNote(contactId) {
      const c = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!c) return;
      const fb = window.prompt('Enter feedback to rewrite note for ' + c.person_name + ' (' + c.company_name + ') & learn rule:', 'Keep it under 12 words, warm and human');
      if (!fb || !fb.trim()) return;
      showToast('🧠 LLM rewriting note for ' + c.person_name + '...', '#38bdf8');
      try {
        const res = await callApi({ action: 'fh_action', contactId, subAction: 'feedback_rewrite', feedback: fb.trim(), learnRule: true });
        applyApiPayload(res);
        showToast(res.message || 'Rewrote note!', '#10b981');
      } catch (e) {
        showToast('Error: ' + e.message, '#f43f5e');
      }
    }

    async function fhItemAction(contactId, subAction) {
      try {
        const res = await callApi({ action: 'fh_action', contactId, subAction });
        applyApiPayload(res);
        showToast(res.message || 'Updated network contact!', '#10b981');
      } catch (e) {
        showToast('Network action error: ' + e.message, '#f43f5e');
      }
    }

    async function addNewFhContact() {
      const personName = (document.getElementById('fh-new-name')?.value || '').trim();
      const company = (document.getElementById('fh-new-company')?.value || '').trim();
      if (!personName || !company) { showToast('Enter Company and Person Name first.', '#f59e0b'); return; }
      try {
        const res = await callApi({
          action: 'fh_action',
          subAction: 'add',
          category: document.getElementById('fh-new-cat')?.value || '🎯 HR / Talent Acquisition',
          company,
          personName,
          roleTitle: document.getElementById('fh-new-role')?.value || '',
          location: document.getElementById('fh-new-loc')?.value || 'Gurugram / Bengaluru, India',
          profileUrl: document.getElementById('fh-new-url')?.value || '',
