    function togglePortalExpand(siteName) {
      STATE.expandedPortal = (STATE.expandedPortal === siteName) ? '' : siteName;
      renderPortalsVaultInteractive();
    }

    function renderPortalsVaultInteractive() {
      const tbBox = document.getElementById('portals-interactive-toolbar');
      const pBox = document.getElementById('portals-list-box');
      if (!pBox) return;

      const b = getPortalDateBounds();
      const preset = STATE.portalDatePreset || 'yesterday';
      const presetLabels = {
        yesterday: `Yesterday (${b.yesterdayIso})`,
        today: `Today (${b.todayIso})`,
        last7: `Last 7 Days (${b.last7Iso} \u2192 ${b.todayIso})`,
        last30: `Last 30 Days`,
        month: `This Month (${b.monthStartIso.slice(0, 7)})`,
        all: `All Time`,
        custom: `Custom (${STATE.portalCustomFrom || 'Start'} \u2192 ${STATE.portalCustomTo || 'Now'})`
      };
      const periodLabel = presetLabels[preset] || 'Selected Period';

      const rawVault = Array.isArray(STATE.vaultRows) ? STATE.vaultRows : [];
      const seenSites = new Set();
      const unifiedPortals = [];
      const addPortalEntry = (v) => {
        const key = String(v.site_name || '').trim();
        if (!key) return;
        const norm = key.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (norm === 'builtinindiaremote' && seenSites.has('builtinremoteindia')) return;
        if (norm === 'himalayasapp' && seenSites.has('himalayas')) return;
        if (seenSites.has(norm)) return;
        seenSites.add(norm);
        unifiedPortals.push(v);
      };
      rawVault.forEach(addPortalEntry);
      addPortalEntry({ site_name: 'Company Career Sites (Direct)', portal_url: '', auth_email: 'user@example.com', auth_status: 'Direct ATS / Career Portals' });
      addPortalEntry({ site_name: 'Referral & Direct Email', portal_url: '', auth_email: 'user@example.com', auth_status: 'Insider Referrals & 008 SMTP' });

      const allJobs = Array.isArray(STATE.jobs) ? STATE.jobs : [];
      const enrichedJobs = allJobs.map(j => {
        const isApplied = j.stageBucket === 'Applied' || j.stageBucket === 'Interviewing' || j.stageBucket === 'Offer' || Boolean(String(j.appliedOn || '').trim());
        const appliedIso = isApplied ? (parseJobIsoDate(j.appliedOn) || parseJobIsoDate(j.lastUpdated) || parseJobIsoDate(j.createdOn)) : '';
        const createdIso = parseJobIsoDate(j.createdOn) || parseJobIsoDate(j.lastUpdated) || appliedIso;
        const portalKey = mapJobToPortalName(j);
        return { ...j, _isApplied: isApplied, _appliedIso: appliedIso, _createdIso: createdIso, _portalKey: portalKey };
      });

      const totalAppliedYesterday = enrichedJobs.filter(j => j._isApplied && j._appliedIso === b.yesterdayIso).length;
      const totalQueuedYesterday = enrichedJobs.filter(j => j._createdIso === b.yesterdayIso).length;
      const totalAppliedToday = enrichedJobs.filter(j => j._isApplied && j._appliedIso === b.todayIso).length;
      const totalQueuedToday = enrichedJobs.filter(j => j._createdIso === b.todayIso).length;
      const totalApplied7d = enrichedJobs.filter(j => j._isApplied && dateMatchesPortalFilter(j._appliedIso, 'last7', b)).length;
      const totalApplied30d = enrichedJobs.filter(j => j._isApplied && dateMatchesPortalFilter(j._appliedIso, 'last30', b)).length;
      const totalAppliedAll = enrichedJobs.filter(j => j._isApplied).length;

      const portalStats = unifiedPortals.map(v => {
        const sName = v.site_name;
        const lim = (STATE.limitRows || []).find(l => String(l.site_name || '').toLowerCase().includes(sName.toLowerCase().split(' ')[0])) || {};
        const pJobs = enrichedJobs.filter(j => j._portalKey.toLowerCase() === sName.toLowerCase());
        const appliedPeriod = pJobs.filter(j => j._isApplied && dateMatchesPortalFilter(j._appliedIso, preset, b));
        const queuedPeriod = pJobs.filter(j => dateMatchesPortalFilter(j._createdIso, preset, b));
        const appliedYest = pJobs.filter(j => j._isApplied && j._appliedIso === b.yesterdayIso);
        const queuedYest = pJobs.filter(j => j._createdIso === b.yesterdayIso);
        const appliedTodayList = pJobs.filter(j => j._isApplied && j._appliedIso === b.todayIso);
        const appliedAll = pJobs.filter(j => j._isApplied);
        const dailyCap = lim.safe_daily_cap || lim.hard_daily_limit || lim.daily_max_limit || 25;
        const todayUsed = Math.max(Number(lim.applies_today || lim.applied_today || 0), appliedTodayList.length);
        return {
          vault: v,
          siteName: sName,
          pJobs,
          appliedPeriod,
          queuedPeriod,
          appliedYest,
          queuedYest,
          appliedAll,
          dailyCap,
          todayUsed
        };
      });

      const totalAppliedPeriod = portalStats.reduce((s, p) => s + p.appliedPeriod.length, 0);
      const totalQueuedPeriod = portalStats.reduce((s, p) => s + p.queuedPeriod.length, 0);
      const activePortalsCount = portalStats.filter(p => p.appliedPeriod.length > 0 || p.queuedPeriod.length > 0).length;
      const appliedPortalsCount = portalStats.filter(p => p.appliedPeriod.length > 0).length;

      if (tbBox) {
        const pBtn = (id, label) => `<button class="btn btn-sm ${preset === id ? 'btn-primary' : ''}" onclick="setPortalDatePreset('${id}')">${label}</button>`;
        const fBtn = (id, label) => `<button class="btn btn-sm ${STATE.portalActivityFilter === id ? 'btn-emerald' : ''}" onclick="setPortalActivityFilter('${id}')">${label}</button>`;
        tbBox.innerHTML = `
          <div style="background:#090f1d; border:1px solid var(--border); border-radius:10px; padding:10px 12px; display:flex; flex-direction:column; gap:10px;">
            <div style="display:flex; flex-wrap:wrap; gap:6px; align-items:center; justify-content:space-between;">
              <div style="display:flex; flex-wrap:wrap; gap:5px; align-items:center;">
                <span style="font-size:11px; font-weight:700; color:var(--muted); margin-right:4px;">\ud83d\udcc5 DATE FILTER:</span>
                ${pBtn('yesterday', `\u23ee\ufe0f Yesterday (${totalAppliedYesterday} Applied \u2022 ${totalQueuedYesterday} Queued)`)}
                ${pBtn('today', `\ud83d\udcc5 Today (${totalAppliedToday} Applied \u2022 ${totalQueuedToday} Queued)`)}
                ${pBtn('last7', `\ud83d\udcc6 Last 7d (${totalApplied7d})`)}
                ${pBtn('last30', `\ud83d\uddd3\ufe0f Last 30d (${totalApplied30d})`)}
                ${pBtn('month', `\ud83d\udcca This Month`)}
                ${pBtn('all', `\ud83c\udf10 All Time (${totalAppliedAll} Applied)`)}
              </div>
              <div style="display:flex; gap:5px; align-items:center; flex-wrap:wrap;">
                <input type="date" id="portal-date-from" value="${escHtml(STATE.portalCustomFrom)}" onchange="setPortalCustomDates()" style="padding:4px 7px; font-size:11px; width:122px;" title="From Date" />
                <span style="color:var(--muted); font-size:11px;">\u2192</span>
                <input type="date" id="portal-date-to" value="${escHtml(STATE.portalCustomTo)}" onchange="setPortalCustomDates()" style="padding:4px 7px; font-size:11px; width:122px;" title="To Date" />
              </div>
            </div>

            <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(145px, 1fr)); gap:8px;">
              <div onclick="setPortalDatePreset('yesterday')" style="cursor:pointer; background:rgba(56,189,248,0.08); border:1px solid rgba(56,189,248,0.3); border-radius:8px; padding:8px 10px;">
                <div style="font-size:10.5px; color:#38bdf8; font-weight:700;">\u23ee\ufe0f APPLIED YESTERDAY (${b.yesterdayIso})</div>
                <div style="font-size:18px; font-weight:900; color:#f8fafc; margin-top:2px;">${totalAppliedYesterday} Jobs Applied</div>
                <div style="font-size:10.5px; color:var(--muted);">+ ${totalQueuedYesterday} jobs queued/discovered yesterday</div>
              </div>
              <div style="background:rgba(16,185,129,0.08); border:1px solid rgba(16,185,129,0.3); border-radius:8px; padding:8px 10px;">
                <div style="font-size:10.5px; color:#34d399; font-weight:700;">\u2705 APPLIED IN PERIOD</div>
                <div style="font-size:18px; font-weight:900; color:#f8fafc; margin-top:2px;">${totalAppliedPeriod} Applied</div>
                <div style="font-size:10.5px; color:var(--muted);">${escHtml(periodLabel)}</div>
              </div>
              <div style="background:rgba(168,85,247,0.08); border:1px solid rgba(168,85,247,0.3); border-radius:8px; padding:8px 10px;">
                <div style="font-size:10.5px; color:#c084fc; font-weight:700;">\ud83d\udce5 QUEUED / DISCOVERED</div>
                <div style="font-size:18px; font-weight:900; color:#f8fafc; margin-top:2px;">${totalQueuedPeriod} Jobs</div>
                <div style="font-size:10.5px; color:var(--muted);">In ${escHtml(periodLabel)}</div>
              </div>
              <div style="background:rgba(245,158,11,0.08); border:1px solid rgba(245,158,11,0.3); border-radius:8px; padding:8px 10px;">
                <div style="font-size:10.5px; color:#fbbf24; font-weight:700;">\ud83c\udfc6 ACTIVE PORTALS</div>
                <div style="font-size:18px; font-weight:900; color:#f8fafc; margin-top:2px;">${activePortalsCount} / ${portalStats.length}</div>
                <div style="font-size:10.5px; color:var(--muted);">Click any portal below to drill down</div>
              </div>
            </div>

            <div style="display:flex; flex-wrap:wrap; gap:6px; justify-content:space-between; align-items:center;">
              <div style="display:flex; gap:5px; flex-wrap:wrap;">
                ${fBtn('all', `All Portals (${portalStats.length})`)}
                ${fBtn('active', `\ud83d\udd25 Active in Period (${activePortalsCount})`)}
                ${fBtn('applied', `\u2705 Applied > 0 (${appliedPortalsCount})`)}
              </div>
              <input type="text" placeholder="\ud83d\udd0d Search portal or company..." value="${escHtml(STATE.portalSearch)}" oninput="onPortalSearchInput(this.value)" style="padding:5px 10px; font-size:11.5px; width:210px;" />
            </div>
          </div>
        `;
      }

      const qLow = String(STATE.portalSearch || '').trim().toLowerCase();
      let filtered = portalStats.filter(p => {
        if (STATE.portalActivityFilter === 'active' && p.appliedPeriod.length === 0 && p.queuedPeriod.length === 0) return false;
        if (STATE.portalActivityFilter === 'applied' && p.appliedPeriod.length === 0) return false;
        if (qLow) {
          const matchSite = p.siteName.toLowerCase().includes(qLow);
          const matchComp = p.pJobs.some(j => String(j.company || '').toLowerCase().includes(qLow) || String(j.title || '').toLowerCase().includes(qLow));
          if (!matchSite && !matchComp) return false;
        }
        return true;
      });

      filtered.sort((a, b2) => {
        if (b2.appliedPeriod.length !== a.appliedPeriod.length) return b2.appliedPeriod.length - a.appliedPeriod.length;
        if (b2.queuedPeriod.length !== a.queuedPeriod.length) return b2.queuedPeriod.length - a.queuedPeriod.length;
        if (b2.appliedAll.length !== a.appliedAll.length) return b2.appliedAll.length - a.appliedAll.length;
        return a.siteName.localeCompare(b2.siteName);
      });

      if (filtered.length === 0) {
        pBox.innerHTML = `<div style="padding:20px; text-align:center; color:var(--muted); border:1px dashed var(--border); border-radius:10px;">No portals matched the current filter (${escHtml(periodLabel)}). Try clicking "All Portals" or "All Time".</div>`;
        return;
      }

      pBox.innerHTML = filtered.map(p => {
        const v = p.vault;
        const isExp = STATE.expandedPortal === p.siteName;
        const periodJobs = [...p.appliedPeriod, ...p.queuedPeriod.filter(x => !p.appliedPeriod.some(a => a.sNo === x.sNo))];
        const jobsForDrawer = periodJobs.length > 0 ? periodJobs : p.pJobs.slice(0, 15);
        const safeSiteJs = p.siteName.replace(/'/g, "\\'");

        const drawerHtml = isExp ? `
          <div style="margin-top:8px; padding-top:8px; border-top:1px solid var(--border);">
            <div style="font-size:11px; font-weight:700; color:#38bdf8; margin-bottom:6px;">
              ${periodJobs.length > 0 ? `\ud83d\udccb Jobs in ${escHtml(periodLabel)} (${periodJobs.length}):` : `\ud83d\udccb No jobs in ${escHtml(periodLabel)} \u2014 Showing All-Time Jobs for ${escHtml(p.siteName)} (${p.pJobs.length}):`}
            </div>
            ${jobsForDrawer.length === 0
              ? `<div style="font-size:11.5px; color:var(--muted); padding:6px 0;">No jobs logged for this portal yet.</div>`
              : `<div style="display:flex; flex-direction:column; gap:5px; max-height:220px; overflow-y:auto;">
                  ${jobsForDrawer.map(j => `
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:6px 8px; background:#050811; border:1px solid var(--border); border-radius:7px; font-size:11.5px;">
                      <div>
                        <span class="mono" style="color:#38bdf8; font-weight:700;">#${escHtml(j.sNo)}</span>
                        <strong style="color:#f8fafc; margin-left:4px;">${escHtml(j.company)}</strong>
                        <span style="color:var(--muted);"> \u2014 ${escHtml(j.title)}</span>
                        <div style="font-size:10.5px; color:var(--muted); margin-top:2px;">
                          Status: <span class="badge ${j._isApplied ? 'b-emerald' : 'b-amber'}" style="font-size:9.5px; padding:1px 5px;">${escHtml(j.status)}</span>
                          ${j._appliedIso ? ` \u2022 Applied: <strong style="color:#34d399;">${escHtml(j._appliedIso)}</strong>` : ''}
                          ${j._createdIso ? ` \u2022 Queued: ${escHtml(j._createdIso)}` : ''}
                        </div>
                      </div>
                      <div style="display:flex; gap:5px; flex-shrink:0;">
                        <button class="btn btn-sm btn-primary" onclick="event.stopPropagation(); openJobInStudio('${escHtml(j.sNo)}', 'resume')">\ud83c\udfac Studio</button>
                        ${!j._isApplied ? `<button class="btn btn-sm btn-emerald" onclick="event.stopPropagation(); quickStageUpdate('Applied', '${escHtml(j.sNo)}')">\u2705 Mark Applied</button>` : ''}
                      </div>
                    </div>
                  `).join('')}
                </div>`
            }
          </div>
        ` : '';

        return `
          <div onclick="togglePortalExpand('${safeSiteJs}')" style="cursor:pointer; background:#090f1d; border:1px solid ${p.appliedPeriod.length > 0 ? 'rgba(16,185,129,0.45)' : (p.queuedPeriod.length > 0 ? 'rgba(56,189,248,0.4)' : 'var(--border)')}; border-radius:10px; padding:10px 12px; transition:all 0.15s;">
            <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
              <div>
                <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                  <span style="font-weight:800; color:#f8fafc; font-size:13px;">${escHtml(p.siteName)}</span>
                  ${v.portal_url ? `<a href="${escHtml(v.portal_url)}" target="_blank" onclick="event.stopPropagation();" class="badge b-sky" style="text-decoration:none; font-size:10px;">\u2197 Portal</a>` : ''}
                  <span style="font-size:10.5px; color:var(--muted);">(${p.pJobs.length} total tracked)</span>
                </div>
                <div style="font-size:11px; color:var(--muted); margin-top:2px;">
                  ${escHtml(v.auth_email || 'user@example.com')} \u2022 ${escHtml(v.auth_status || 'Configured')}
                  \u2022 <span style="color:#cbd5e1;">Yesterday: <strong>${p.appliedYest.length} Applied</strong> (${p.queuedYest.length} Queued)</span>
                  \u2022 <span style="color:#94a3b8;">All-Time: <strong>${p.appliedAll.length} Applied</strong></span>
                </div>
              </div>
              <div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap;">
                <span class="badge ${p.appliedPeriod.length > 0 ? 'b-emerald' : 'b-slate'} mono" title="Jobs Applied in ${escHtml(periodLabel)}">\u2705 ${p.appliedPeriod.length} Applied</span>
