    rule: `${secUpper} — MANDATORY LLM DIRECTIVE: ${bodyDirective}${banSuffix}. Enforce this rule strictly across all future generations.`
  };
};

const buildQualitativeSummary = (title, jd) => {
  const combined = `${title || ''} ${jd || ''}`.toLowerCase();
  let s2 = `Proven track record of architecting automated data pipelines and interactive KPI reporting suites using <strong>SQL, Python, and Tableau</strong> to streamline reporting workflows, resolve operational bottlenecks, and elevate cross-functional delivery quality.`;
  if (/product|growth|funnel|experiment|retention|marketing/i.test(combined)) {
    s2 = `Proven track record of applying <strong>SQL, Python, and Tableau</strong> across product, growth, and commercial datasets to uncover conversion bottlenecks, automate recurring performance reporting, and guide customer acquisition and retention strategy.`;
  } else if (/financ|fp&a|risk|treasury|payment|commercial|pricing|revenue|monetiz/i.test(combined)) {
    s2 = `Proven track record of leveraging <strong>SQL, Python, and Tableau</strong> for financial reconciliation, commercial pricing analysis, and automated KPI governance across enterprise and regional operations.`;
  } else if (/operations|strategy|consulting|workforce|process|program|business analyst/i.test(combined)) {
    s2 = `Proven track record of utilizing <strong>SQL, Python, and Tableau</strong> to diagnose operational SLA bottlenecks, standardize cross-functional workflows, and scale process efficiency across global teams.`;
  }
  const gList = [
    { p: 'data cleaning and transformation', m: /pipeline|etl|warehouse|bigquery|postgres|sql|model|clean|wrangl|transform/i },
    { p: 'diagnostic root-cause analysis', m: /root-cause|root cause|diagnostic|variance|trend|anomaly|investigat|problem/i },
    { p: 'funnel and cohort segmentation', m: /funnel|cohort|retention|churn|conversion|segment|customer|acquisition/i },
    { p: 'automated dashboard reporting', m: /dashboard|tableau|bi |visualiz|scorecard|kpi|report/i },
    { p: 'workflow automation and QA governance', m: /automat|governance|quality|qa|sla|process|efficiency|streamlin/i },
    { p: 'narrative insight synthesis', m: /stakeholder|executive|storytelling|consulting|strategy|presentation|decision/i }
  ];
  const matched = gList.filter(g => g.m.test(combined)).map(g => g.p);
  const g1 = matched[0] || 'data cleaning and transformation';
  const g2 = matched[1] || (g1 === 'diagnostic root-cause analysis' ? 'narrative insight synthesis' : 'diagnostic root-cause analysis');
  return `<p>Senior Data &amp; Business Analyst combining extensive enterprise data analytics and operations intelligence experience with a strong foundation in commercial strategy and stakeholder consulting. ${s2} Adept at applying <strong>${g1}</strong> and <strong>${g2}</strong> to translate complex datasets into clear executive presentations and actionable business decisions.</p>`;
};

