const extractDriveId = (urlOrId) => {
  const s = String(urlOrId || '').trim();
  if (!s) return '';
  const m1 = s.match(/\/file\/d\/([a-zA-Z0-9_-]{15,})/);
  if (m1) return m1[1];
  const m2 = s.match(/[?&]id=([a-zA-Z0-9_-]{15,})/);
  if (m2) return m2[1];
  if (/^[a-zA-Z0-9_-]{18,}$/.test(s)) return s;
  return '';
};

